-- 0023 — L'univers général choisit aussi son métier.
--
-- Décision du 21 novembre 2026 : les indépendants du tertiaire (juristes,
-- notaires, développeurs, photographes, musiciens, formateurs, services à la
-- personne…) indiquent leur métier à l'inscription, comme les artisans et les
-- praticiens, pour adapter le vocabulaire de leur espace.
--
-- Migration additive : la contrainte est élargie d'une branche « freelance »
-- (aucune ligne existante ne peut la violer, toutes les branches précédentes
-- sont reprises à l'identique). Le script de migration exécute ce fichier dans
-- une seule transaction.

ALTER TABLE public.organizations DROP CONSTRAINT organizations_sector_profession_check;
ALTER TABLE public.organizations ADD CONSTRAINT organizations_sector_profession_check CHECK (((((sector = 'health'::text) AND (profession = ANY (ARRAY['physiotherapist'::text, 'osteopath'::text, 'speech_therapist'::text, 'podiatrist'::text, 'occupational_therapist'::text, 'psychomotor_therapist'::text, 'dietitian'::text, 'psychologist'::text, 'sport_coach'::text, 'nutritionist'::text, 'wellness_massage'::text]))) OR ((sector = ANY (ARRAY['field_services'::text, 'artisan'::text])) AND (profession = ANY (ARRAY['mason'::text, 'plumber'::text, 'electrician'::text, 'heating_technician'::text, 'hvac_technician'::text, 'roofer'::text, 'carpenter'::text, 'joiner'::text, 'painter'::text, 'plasterer'::text, 'insulation_specialist'::text, 'tiler'::text, 'earthworks_contractor'::text, 'facade_specialist'::text, 'locksmith'::text, 'glazier'::text, 'sanitation_specialist'::text, 'renovation_contractor'::text, 'pool_specialist'::text, 'architect'::text, 'construction_project_manager'::text, 'engineering_office'::text, 'quantity_surveyor'::text, 'maintenance_technician'::text, 'technical_installer'::text, 'auto_mechanic'::text, 'auto_body_repairer'::text, 'auto_service_center'::text, 'phone_repairer'::text, 'computer_repairer'::text, 'appliance_repairer'::text, 'electronics_repairer'::text, 'landscaper'::text, 'custom_manufacturer'::text, 'artisan_retailer'::text, 'technical_service_provider'::text]))) OR ((sector = 'freelance'::text) AND (profession = ANY (ARRAY['lawyer'::text, 'legal_advisor'::text, 'notary'::text, 'bailiff'::text, 'accountant'::text, 'wealth_advisor'::text, 'insurance_broker'::text, 'real_estate_agent'::text, 'business_consultant'::text, 'it_consultant'::text, 'hr_consultant'::text, 'virtual_assistant'::text, 'web_developer'::text, 'graphic_designer'::text, 'photographer'::text, 'videographer'::text, 'community_manager'::text, 'copywriter'::text, 'translator'::text, 'architect_interior'::text, 'musician'::text, 'dj'::text, 'event_planner'::text, 'entertainer'::text, 'artist'::text, 'trainer'::text, 'private_tutor'::text, 'business_coach'::text, 'music_teacher'::text, 'home_cleaning'::text, 'home_help'::text, 'childcare'::text, 'pet_care'::text, 'concierge'::text]))) OR (profession IS NULL)) AND (NOT ((sector IS NULL) AND (profession IS NOT NULL)))));
